(2112966, 287474, 31812, '<td valign="top">Beautifully done. Love the simple straightforward elegance of this.</td>', 'Beautifully done. Love the simple straightforward elegance of this.', '2006-02-01 23:05:51.000000', NULL, 1),
(2112971, 288010, 31812, '<td valign="top">Clever. I like how you were able to work in other colours and still have blue be the main focal colour. Good job.</td>', 'Clever. I like how you were able to work in other colours and still have blue be the main focal colour. Good job.', '2006-02-01 23:06:43.000000', NULL, 1),
(2112973, 286096, 30982, '<td valign="top">Not having been there I can''t really say, but I think if you''d taken the picture a few steps forward, without the door to the right of the pic, it would be a more balanced composition..  I do like the lighting further down - nice contrast to the blue of the bridge.</td>', 'Not having been there I can''t really say, but I think if you''d taken the picture a few steps forward, without the door to the right of the pic, it would be a more balanced composition..  I do like the lighting further down - nice contrast to the blue of the bridge.', '2006-02-01 23:06:54.000000', NULL, 1),
(2112976, 286410, 31812, '<td valign="top">I like the lines here. Very clean and smooth.</td>', 'I like the lines here. Very clean and smooth.', '2006-02-01 23:07:23.000000', NULL, 1),
(2112979, 287522, 31812, '<td valign="top">Nice DOF, but I wish the drop was a little more in focus.</td>', 'Nice DOF, but I wish the drop was a little more in focus.', '2006-02-01 23:07:56.000000', NULL, 1),
(2112981, 288110, 49773, '<td valign="top">dark blue, but still blue, good stretch,i like the composition very much</td>', 'dark blue, but still blue, good stretch,i like the composition very much', '2006-02-01 23:08:18.000000', NULL, 1),
(2112983, 286720, 31812, '<td valign="top">Nice interpretation, and I like the monochromatic blues exampled here.</td>', 'Nice interpretation, and I like the monochromatic blues exampled here.', '2006-02-01 23:08:56.000000', NULL, 1),
(2112995, 288548, 31812, '<td valign="top">Clever! I like the DOF and the two unexpected elements of egg and tape measure.</td>', 'Clever! I like the DOF and the two unexpected elements of egg and tape measure.', '2006-02-01 23:11:28.000000', NULL, 1),
(2113002, 286590, 31812, '<td valign="top">Very clever with the reflection here, though the nib(?) looks over sharpened to me. I like the reflection of light in this shot though.</td>', 'Very clever with the reflection here, though the nib(?) looks over sharpened to me. I like the reflection of light in this shot though.', '2006-02-01 23:12:56.000000', NULL, 1),
(2113004, 286571, 30982, '<td valign="top">Almost a bit too blue!  For balance, I think having the tram a little further right might be nice.  I like the red contrast - adds a nice spark to the picture.</td>', 'Almost a bit too blue!  For balance, I think having the tram a little further right might be nice.  I like the red contrast - adds a nice spark to the picture.', '2006-02-01 23:13:05.000000', NULL, 1),
(2113014, 289109, 31812, '<td valign="top">The eyes don''t really stand out to me here. It''s a nicely composed and lighted portrait. I just don''t feel the blue of the eyes so much.</td>', 'The eyes don''t really stand out to me here. It''s a nicely composed and lighted portrait. I just don''t feel the blue of the eyes so much.', '2006-02-01 23:14:23.000000', NULL, 1),
(2113020, 289169, 30982, '<td valign="top">I like the perspective but you cut off the top!</td>', 'I like the perspective but you cut off the top!', '2006-02-01 23:15:05.000000', NULL, 1),
(2113033, 288253, 30982, '<td valign="top">Lovely contrast, nice lines.</td>', 'Lovely contrast, nice lines.', '2006-02-01 23:17:37.000000', NULL, 1),
