(2113076, 285954, 30982, '<td valign="top">Nice leading line, great color in the wave.  Don''t like the extra guy in the pic but what are you gonna do?  It was very nice of the guy on the wave to have that green stripe, though.  Nicely accents the picture.</td>', 'Nice leading line, great color in the wave.  Don''t like the extra guy in the pic but what are you gonna do?  It was very nice of the guy on the wave to have that green stripe, though.  Nicely accents the picture.', '2006-02-01 23:27:32.000000', NULL, 1),
(2113080, 286214, 30982, '<td valign="top">Very pleasing and eye-catching.</td>', 'Very pleasing and eye-catching.', '2006-02-01 23:28:13.000000', NULL, 1),
(2113111, 288426, 30982, '<td valign="top">The composition is well balanced but I''d like to see more light and focus on the eye.</td>', 'The composition is well balanced but I''d like to see more light and focus on the eye.', '2006-02-01 23:37:42.000000', NULL, 1),
(2113113, 288693, 30982, '<td valign="top">Unique entry!  Not sure about teh "sparklies" in the wet parts of the mud, but the different textures and the blues are great!</td>', 'Unique entry!  Not sure about teh "sparklies" in the wet parts of the mud, but the different textures and the blues are great!', '2006-02-01 23:38:30.000000', NULL, 1),
(2113114, 287857, 40430, '<td valign="top">Book ''Em, Danno.  Good capture of police in action.</td>', 'Book ''Em, Danno.  Good capture of police in action.', '2006-02-01 23:38:33.000000', NULL, 1),
(2113119, 288882, 40430, '<td valign="top">Work this boat for a littlelonger and you will probably end up with a stronger image.  great color and texture in this shot.</td>', 'Work this boat for a littlelonger and you will probably end up with a stronger image.  great color and texture in this shot.', '2006-02-01 23:39:43.000000', NULL, 1),
