(2115136, 288669, 51527, '<td valign="top">I would have prefered it without the camera man personally. Still a great shot.</td>', 'I would have prefered it without the camera man personally. Still a great shot.', '2006-02-02 15:34:50.000000', NULL, 1),
(2115142, 288702, 51527, '<td valign="top">Where is that. Calatrava?</td>', 'Where is that. Calatrava?', '2006-02-02 15:37:08.000000', NULL, 1),
(2115151, 286947, 51527, '<td valign="top">Frank Gerhy? Very cool.</td>', 'Frank Gerhy? Very cool.', '2006-02-02 15:40:17.000000', NULL, 1),
(2115188, 288906, 52596, '<td valign="top">Ah, I like this one - I''ve been hard-pressed to find one I really liked in this challenge. Good job and NOT over saturating the blues. Too often people over-saturate their color. The only thing I might have done differently would be to match the blue of the water on the ground with the blue in the sky, but other than that, very nice all-around.</td>', 'Ah, I like this one - I''ve been hard-pressed to find one I really liked in this challenge. Good job and NOT over saturating the blues. Too often people over-saturate their color. The only thing I might have done differently would be to match the blue of the water on the ground with the blue in the sky, but other than that, very nice all-around.', '2006-02-02 15:58:26.000000', NULL, 1),
(2115221, 289324, 50740, '<td valign="top">Just beautiful, Gringo! Makes me feel like Im flying just looking at it. Good job!</td>', 'Just beautiful, Gringo! Makes me feel like Im flying just looking at it. Good job!', '2006-02-02 16:11:35.000000', NULL, 1),
(2115224, 286480, 48147, '<td valign="top">Needs more than just a blue background in my opinion.</td>', 'Needs more than just a blue background in my opinion.', '2006-02-02 16:11:56.000000', NULL, 1),
(2115229, 289093, 48147, '<td valign="top">A backlit bottle of water? I''d expect more.</td>', 'A backlit bottle of water? I''d expect more.', '2006-02-02 16:12:32.000000', NULL, 1),
(2115231, 286410, 52596, '<td valign="top">Yeah, great composition on this one - I like that you kept it simple and the eye bounces between the metalic textures on the car and the flat finish of the paint on the walls. Interesting.</td>', 'Yeah, great composition on this one - I like that you kept it simple and the eye bounces between the metalic textures on the car and the flat finish of the paint on the walls. Interesting.', '2006-02-02 16:12:43.000000', NULL, 1),
(2115234, 287606, 48147, '<td valign="top">Too simple for me.</td>', 'Too simple for me.', '2006-02-02 16:13:10.000000', NULL, 1),
