(2115238, 286899, 48147, '<td valign="top">I don''t get it.</td>', 'I don''t get it.', '2006-02-02 16:13:45.000000', NULL, 1),
(2115245, 287574, 48147, '<td valign="top">Very simple. Needs more blue I think, but I really love the needle. The needle and the textures really make this one stand out for me. The contrast of metal and cloth fibers is very apparent. If it had more blue, I''d have given it a 10.</td>', 'Very simple. Needs more blue I think, but I really love the needle. The needle and the textures really make this one stand out for me. The contrast of metal and cloth fibers is very apparent. If it had more blue, I''d have given it a 10.', '2006-02-02 16:15:55.000000', NULL, 1),
(2115251, 288949, 52596, '<td valign="top">This is a great scene! I''m not sure if that''s the original color and saturation level on the boat, but I might have used a diffused blue here to be more fitting with the other elements in the scene - not aqua, but maybe a dry or dusty baby blue - steel blue but not too close to the grey backgrouund either. I think the contrast of the aqua seems a bit out of place, but overall a great shot. Love it.</td>', 'This is a great scene! I''m not sure if that''s the original color and saturation level on the boat, but I might have used a diffused blue here to be more fitting with the other elements in the scene - not aqua, but maybe a dry or dusty baby blue - steel blue but not too close to the grey backgrouund either. I think the contrast of the aqua seems a bit out of place, but overall a great shot. Love it.', '2006-02-02 16:16:54.000000', NULL, 1),
