INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2117008, 286845, 41574, '<td valign="top">Why, it''s now my favorite color (well, not really [that would be black]). Anyway, it''s a good shot; the subject matter, alone, warrants a decent score. The sharpness, however, could be better.</td>', 'Why, it''s now my favorite color (well, not really [that would be black]). Anyway, it''s a good shot; the subject matter, alone, warrants a decent score. The sharpness, however, could be better.', '2006-02-03 02:19:58.000000', NULL, 1),
(2117011, 288244, 41574, '<td valign="top">Never include timestamps on your photographs (unless its for some specific "atristic" purpose); doing so immediately invokes a "snapshot" ambiance. The shot, itself, is OK, thought not terribly interesting.</td>', 'Never include timestamps on your photographs (unless its for some specific "atristic" purpose); doing so immediately invokes a "snapshot" ambiance. The shot, itself, is OK, thought not terribly interesting.', '2006-02-03 02:23:35.000000', NULL, 1),
(2117015, 287857, 41574, '<td valign="top">Man, I''m kind of torn. As stated in your title, this clearly is not "artistic photography"; it''s "photo-journalistic." As such, it''s a good shot (well-composed, clear, interesting, etc.). Also, it accomplishes the task of the challenge ("boys in blue" [cops], guy in a blue shirt, blue streaks of police car). I can''t give it a "10," because I can''t fight my predilection for looking for "artfulness," but I have to say that it''s a great shot "of its kind."</td>', 'Man, I''m kind of torn. As stated in your title, this clearly is not "artistic photography"; it''s "photo-journalistic." As such, it''s a good shot (well-composed, clear, interesting, etc.). Also, it accomplishes the task of the challenge ("boys in blue" [cops], guy in a blue shirt, blue streaks of police car). I can''t give it a "10," because I can''t fight my predilection for looking for "artfulness," but I have to say that it''s a great shot "of its kind."', '2006-02-03 02:26:39.000000', NULL, 1),
(2117017, 288949, 41574, '<td valign="top">Wow. The clarity of this picture is amazing. This is the type of sharpness I''ve been seeking, and the type that I had not yet found. I love the "selective blue," and the composition is superb. Terrifically great work.</td>', 'Wow. The clarity of this picture is amazing. This is the type of sharpness I''ve been seeking, and the type that I had not yet found. I love the "selective blue," and the composition is superb. Terrifically great work.', '2006-02-03 02:28:44.000000', NULL, 1),
(2117019, 286904, 41574, '<td valign="top">I love the idea (I''m assuming it''s staged), but your depth of field really hurts. I found myself struggling to make out the right side of your letter, every time I hit that edge of the frame.</td>', 'I love the idea (I''m assuming it''s staged), but your depth of field really hurts. I found myself struggling to make out the right side of your letter, every time I hit that edge of the frame.', '2006-02-03 02:31:03.000000', NULL, 1),
(2117030, 287744, 41574, '<td valign="top">Man, great clarity, adorable subject matter, challenge met...I love it.</td>', 'Man, great clarity, adorable subject matter, challenge met...I love it.', '2006-02-03 02:43:44.000000', NULL, 1),
(2117084, 286778, 46336, '<td valign="top">Um, I''m not sure what this is. For me there is too much happening, with no central focal point. I''m at a lose on what to make of it all.</td>', 'Um, I''m not sure what this is. For me there is too much happening, with no central focal point. I''m at a lose on what to make of it all.', '2006-02-03 03:47:03.000000', NULL, 1),
(2117085, 288641, 46336, '<td valign="top">Different. I''d have been a whole lot more generous if this was the right way up. Actually a very nice shot.</td>', 'Different. I''d have been a whole lot more generous if this was the right way up. Actually a very nice shot.', '2006-02-03 03:48:59.000000', NULL, 1),
(2117086, 289266, 51638, '<td valign="top">Sorry, but I just don''t see the point of changing the colour of something completely unrelated to ''blue'' to meet the challenge criteria.</td>', 'Sorry, but I just don''t see the point of changing the colour of something completely unrelated to ''blue'' to meet the challenge criteria.', '2006-02-03 03:52:29.000000', NULL, 1),
(2117089, 286657, 51638, '<td valign="top">Sorry, but I just don''t want to look at the overblown area smack in the middle of the image. Maybe it''s just me.</td>', 'Sorry, but I just don''t want to look at the overblown area smack in the middle of the image. Maybe it''s just me.', '2006-02-03 03:57:14.000000', NULL, 1),
(2117091, 288943, 51638, '<td valign="top">Very nice clarity to the pic.</td>', 'Very nice clarity to the pic.', '2006-02-03 03:59:01.000000', NULL, 1),
(2117092, 288841, 51638, '<td valign="top">Interesting.</td>', 'Interesting.', '2006-02-03 03:59:49.000000', NULL, 1),
(2117102, 289398, 52296, '<td valign="top">Nice composition, love the blue/black tones, should be in the top of the theme!</td>', 'Nice composition, love the blue/black tones, should be in the top of the theme!', '2006-02-03 04:25:38.000000', NULL, 1),
(2117105, 288649, 52296, '<td valign="top">I would like to know how you do this, looks unreal but great!</td>', 'I would like to know how you do this, looks unreal but great!', '2006-02-03 04:27:52.000000', NULL, 1),
