(2118831, 287272, 43682, '<td valign="top">I like the feeling of the water moving in this shot. Although perhaps I would have increased the saturation a little to enhance the blue.</td>', 'I like the feeling of the water moving in this shot. Although perhaps I would have increased the saturation a little to enhance the blue.', '2006-02-03 15:13:38.000000', NULL, 1),
(2118833, 288653, 43682, '<td valign="top">Great shot. Love the blue haze with the slight pink glare in the sky.</td>', 'Great shot. Love the blue haze with the slight pink glare in the sky.', '2006-02-03 15:14:16.000000', NULL, 1),
