(2118871, 288304, 43682, '<td valign="top">I get the theme of "blue", but would have liked the blue to be more of the focus rather than the window itself.</td>', 'I get the theme of "blue", but would have liked the blue to be more of the focus rather than the window itself.', '2006-02-03 15:22:53.000000', NULL, 1),
(2118882, 286986, 43682, '<td valign="top">Beautiful portrait. Perhaps would have liked the background to be slightly more in focus, although get the idea.</td>', 'Beautiful portrait. Perhaps would have liked the background to be slightly more in focus, although get the idea.', '2006-02-03 15:26:13.000000', NULL, 1),
(2118886, 286457, 43682, '<td valign="top">Wonderful contrasts in this shot</td>', 'Wonderful contrasts in this shot', '2006-02-03 15:26:59.000000', NULL, 1),
