(2119028, 289360, 44490, '<td valign="top">Might be interesting.  But it''s just too dark to see much at all.</td>', 'Might be interesting.  But it''s just too dark to see much at all.', '2006-02-03 16:05:54.000000', NULL, 1),
(2119034, 289352, 44490, '<td valign="top">Seems like it could be interesting with the streaks and bubbles.  But nothing in the image is sharp, so the image is unlikely to get good scores.</td>', 'Seems like it could be interesting with the streaks and bubbles.  But nothing in the image is sharp, so the image is unlikely to get good scores.', '2006-02-03 16:07:18.000000', NULL, 1),
(2119035, 287434, 44490, '<td valign="top">Nice use of mirror.  Focus on central subject would be better, and much more DOF is needed, especially with close subjects.  Off-camera lighting would be better, as the near subject is "blown out" with loss of detail.</td>', 'Nice use of mirror.  Focus on central subject would be better, and much more DOF is needed, especially with close subjects.  Off-camera lighting would be better, as the near subject is "blown out" with loss of detail.', '2006-02-03 16:07:22.000000', NULL, 1),
(2119038, 288908, 44490, '<td valign="top">Nice smile.  But the image is very fuzzy, and better white levels are needed to move it out of the blue equivalent of too gray.</td>', 'Nice smile.  But the image is very fuzzy, and better white levels are needed to move it out of the blue equivalent of too gray.', '2006-02-03 16:08:55.000000', NULL, 1),
(2119039, 289346, 44490, '<td valign="top">Looks like a nice setup.  But it''s just too dark to see much of anything.</td>', 'Looks like a nice setup.  But it''s just too dark to see much of anything.', '2006-02-03 16:09:01.000000', NULL, 1),
(2119040, 287522, 44490, '<td valign="top">Nice idea.  Better focus, sharpness, and/or more DOF would help.</td>', 'Nice idea.  Better focus, sharpness, and/or more DOF would help.', '2006-02-03 16:09:05.000000', NULL, 1),
