(2123860, 289022, 42638, '<td valign="top">Very interesting picture. Lovely composition but the background color almost mutes the impact of the flower. Nice transition of hues though.</td>', 'Very interesting picture. Lovely composition but the background color almost mutes the impact of the flower. Nice transition of hues though.', '2006-02-05 10:30:32.000000', NULL, 1),
(2123862, 289292, 42638, '<td valign="top">Wow, very playful and colorful picture. Nice shapes.</td>', 'Wow, very playful and colorful picture. Nice shapes.', '2006-02-05 10:31:01.000000', NULL, 1),
(2123866, 288980, 42638, '<td valign="top">Wow, now thats blue! Great capture of all 6 sides showing, I like the free falling feel.</td>', 'Wow, now thats blue! Great capture of all 6 sides showing, I like the free falling feel.', '2006-02-05 10:32:19.000000', NULL, 1),
(2123867, 288667, 42638, '<td valign="top">Wow, great perspective picture. Almost makes me dizzy, Love the shades of blue here.</td>', 'Wow, great perspective picture. Almost makes me dizzy, Love the shades of blue here.', '2006-02-05 10:32:59.000000', NULL, 1),
(2123875, 288641, 42638, '<td valign="top">Interesting picture. Lovely colors and clarity. It puzzles me why you chose to turn this over like that.</td>', 'Interesting picture. Lovely colors and clarity. It puzzles me why you chose to turn this over like that.', '2006-02-05 10:35:38.000000', NULL, 1),
(2123876, 288123, 42638, '<td valign="top">Beautiful clarity, Interesting composition.</td>', 'Beautiful clarity, Interesting composition.', '2006-02-05 10:37:18.000000', NULL, 1),
