(2123883, 287932, 42638, '<td valign="top">Wow, Love it! I have a cat just like him. Great capture of the eyes, not easy for me to do.</td>', 'Wow, Love it! I have a cat just like him. Great capture of the eyes, not easy for me to do.', '2006-02-05 10:39:43.000000', NULL, 1),
(2123887, 288338, 42638, '<td valign="top">Interesting picture, Love the how the lines seem to be dancing. Not sure what it is but I like the hues.</td>', 'Interesting picture, Love the how the lines seem to be dancing. Not sure what it is but I like the hues.', '2006-02-05 10:42:01.000000', NULL, 1),
(2123892, 287677, 42638, '<td valign="top">Wow, Lovely to look at. The blue and yellow are marvelous. Good use of space, nice composition.</td>', 'Wow, Lovely to look at. The blue and yellow are marvelous. Good use of space, nice composition.', '2006-02-05 10:44:55.000000', NULL, 1),
