INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2130114, 288737, 22937, '<td valign="top">Looks a bit shaky to me - snow, sub zero temp? Try using a tripod when shooting in twilight.</td>', 'Looks a bit shaky to me - snow, sub zero temp? Try using a tripod when shooting in twilight.', '2006-02-07 15:42:19.000000', NULL, 1),
(2130115, 286011, 48115, '<td valign="top">lovely.. how did you do that :)</td>', 'lovely.. how did you do that :)', '2006-02-07 15:42:19.000000', NULL, 1),
(2130120, 288238, 48115, '<td valign="top">very nice.. well done 9</td>', 'very nice.. well done 9', '2006-02-07 15:44:03.000000', NULL, 1),
(2130121, 287649, 30982, '<td valign="top">A neat idea, but it would be a better picture if it had more contrast - too much is blue (yeah, I know, it''s "blue" challenge.)  But a "blue" apple against a yellow background would be quite stunning.  Here it tends to blend in too much.</td>', 'A neat idea, but it would be a better picture if it had more contrast - too much is blue (yeah, I know, it''s "blue" challenge.)  But a "blue" apple against a yellow background would be quite stunning.  Here it tends to blend in too much.', '2006-02-07 15:44:13.000000', NULL, 1),
(2130122, 288949, 22937, '<td valign="top">One of the best in Blue II. I hope it''s not just me who fancy this one (8).</td>', 'One of the best in Blue II. I hope it''s not just me who fancy this one (8).', '2006-02-07 15:44:31.000000', NULL, 1),
(2130126, 286590, 48115, '<td valign="top">humm.. how?? whiche that thin at the top wasn''t so grainy..</td>', 'humm.. how?? whiche that thin at the top wasn''t so grainy..', '2006-02-07 15:44:58.000000', NULL, 1),
(2130128, 289177, 30982, '<td valign="top">Yes, the challenge is "Blue" but I''ve come to believe there''s such a thing as too much blue.  I think this would have been a better picture if the balloons had been a different color against the blue background.</td>', 'Yes, the challenge is "Blue" but I''ve come to believe there''s such a thing as too much blue.  I think this would have been a better picture if the balloons had been a different color against the blue background.', '2006-02-07 15:45:45.000000', NULL, 1),
(2130129, 287524, 48115, '<td valign="top">find a better berry next time, not a broken one.. and a better background.. sorry don''t like this..</td>', 'find a better berry next time, not a broken one.. and a better background.. sorry don''t like this..', '2006-02-07 15:45:55.000000', NULL, 1),
(2130130, 286383, 48115, '<td valign="top">hum.. blue/green but nice shot tho</td>', 'hum.. blue/green but nice shot tho', '2006-02-07 15:46:15.000000', NULL, 1),
(2130133, 285983, 30982, '<td valign="top">Gorgeous color in the sky and a unique perspective, but maybe a bit too much empty space for a balanced composition.</td>', 'Gorgeous color in the sky and a unique perspective, but maybe a bit too much empty space for a balanced composition.', '2006-02-07 15:47:25.000000', NULL, 1),
(2130136, 287415, 30982, '<td valign="top">A concept that''s a bit overdone on DPC - might be more effective if you used a dark background to get a bit more contrast.  The shadows of the bubbles does detract, though I don''t know how the folks who do these shots avoid them.</td>', 'A concept that''s a bit overdone on DPC - might be more effective if you used a dark background to get a bit more contrast.  The shadows of the bubbles does detract, though I don''t know how the folks who do these shots avoid them.', '2006-02-07 15:49:05.000000', NULL, 1),
(2130138, 289346, 30982, '<td valign="top">The mask is nice but the picture is too dark.</td>', 'The mask is nice but the picture is too dark.', '2006-02-07 15:49:20.000000', NULL, 1),
(2130142, 288962, 30982, '<td valign="top">Interesting take on the challenge - I like that it''s not ALL blue, but you''re lacking focus on your subject - seems to be sharper focus on the wall.</td>', 'Interesting take on the challenge - I like that it''s not ALL blue, but you''re lacking focus on your subject - seems to be sharper focus on the wall.', '2006-02-07 15:50:08.000000', NULL, 1),
(2130143, 287132, 10858, '<td valign="top">It''s so simple but great. I love the metallic effect on the optical lamp hair, great macro shot! (9)</td>', 'It''s so simple but great. I love the metallic effect on the optical lamp hair, great macro shot! (9)', '2006-02-07 15:50:24.000000', NULL, 1),
(2130151, 288869, 30982, '<td valign="top">Nice gradation of blue in the sky.</td>', 'Nice gradation of blue in the sky.', '2006-02-07 15:52:50.000000', NULL, 1),
(2130166, 288679, 30982, '<td valign="top">If you put your subject further from the background, you can avoid it being a distraction (ie it''s wrinkled) - or so I read on a thread here a while back.  I like the blue liquid but don''t like the blue reflection on her face, though that''s what you were going for, I''m sure.  Just a bit too unnatural for me.</td>', 'If you put your subject further from the background, you can avoid it being a distraction (ie it''s wrinkled) - or so I read on a thread here a while back.  I like the blue liquid but don''t like the blue reflection on her face, though that''s what you were going for, I''m sure.  Just a bit too unnatural for me.', '2006-02-07 15:55:45.000000', NULL, 1),
(2130174, 288279, 30982, '<td valign="top">This is a good idea, and the positioning of the objects is pretty good, but I think a more contrasting background may have worked better - either a whiter white, or a complimentary color.  Not sure what the big shadow across the back of the picture is - it kind of detracts from the hippos'' shadows a little.</td>', 'This is a good idea, and the positioning of the objects is pretty good, but I think a more contrasting background may have worked better - either a whiter white, or a complimentary color.  Not sure what the big shadow across the back of the picture is - it kind of detracts from the hippos'' shadows a little.', '2006-02-07 15:57:55.000000', NULL, 1),
(2130177, 288268, 30982, '<td valign="top">A little small - use the full 640 pixels on the longest side to give viewers a better look.  A good piture, but fairly common picture.  Good use of rule of thirds.</td>', 'A little small - use the full 640 pixels on the longest side to give viewers a better look.  A good piture, but fairly common picture.  Good use of rule of thirds.', '2006-02-07 15:59:18.000000', NULL, 1),
(2130180, 288403, 30982, '<td valign="top">I like this one better the second time through.  It''s a lovely shade of turquoise.  The light on the OOF beads/balls in the back is a bit too harsh, pulling the eye away a bit from those in the front.</td>', 'I like this one better the second time through.  It''s a lovely shade of turquoise.  The light on the OOF beads/balls in the back is a bit too harsh, pulling the eye away a bit from those in the front.', '2006-02-07 16:00:35.000000', NULL, 1),
(2130186, 289252, 30982, '<td valign="top">It''s a pretty flag, but it''s not that interesting as a picture presented here - ie hung on a wall and drooping a bit.  There''s also a circular spot which could be lens flare.  A better picture might have been to have it straightened, on a darker or complimentary background, and maybe from and angle, rather than head on.</td>', 'It''s a pretty flag, but it''s not that interesting as a picture presented here - ie hung on a wall and drooping a bit.  There''s also a circular spot which could be lens flare.  A better picture might have been to have it straightened, on a darker or complimentary background, and maybe from and angle, rather than head on.', '2006-02-07 16:03:00.000000', NULL, 1),
